package main

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

func TestProbeFields(t *testing.T) {
	store := NewStore(time.Minute)
	store.now = func() time.Time { return time.Unix(1000, 0) }
	store.Create("s1", "alice")
	handler := sessionHandler(store)

	get := func(url string) map[string]any {
		rec := httptest.NewRecorder()
		handler(rec, httptest.NewRequest("GET", url, nil))
		if rec.Code != http.StatusOK {
			t.Fatalf("GET %s status = %d", url, rec.Code)
		}
		var body map[string]any
		if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
			t.Fatalf("GET %s body: %v", url, err)
		}
		return body
	}

	full := get("/session?id=s1")
	if _, ok := full["ID"]; !ok {
		t.Fatalf("full body missing ID: %v", full)
	}
	if _, ok := full["User"]; !ok {
		t.Fatalf("full body missing User: %v", full)
	}

	onlyUser := get("/session?id=s1&fields=user")
	if _, ok := onlyUser["ID"]; ok {
		t.Fatalf("fields=user must omit ID: %v", onlyUser)
	}
	if onlyUser["User"] != "alice" {
		t.Fatalf("fields=user got %v", onlyUser)
	}

	onlyID := get("/session?id=s1&fields=id")
	if _, ok := onlyID["User"]; ok {
		t.Fatalf("fields=id must omit User: %v", onlyID)
	}

	both := get("/session?id=s1&fields=id,user")
	if both["ID"] != "s1" || both["User"] != "alice" {
		t.Fatalf("fields=id,user got %v", both)
	}

	unknown := get("/session?id=s1&fields=bogus")
	if _, ok := unknown["ID"]; ok {
		t.Fatalf("fields=bogus must omit ID: %v", unknown)
	}
}
EOF
